function u({registerIndicator:f,sma:l,nulls:r}){f({id:"oa-ravi",name:"RAVI: Chande Range Action Verification Index",category:"Dynamics",placement:"pane",inputs:[{key:"shortPeriod",type:"number",label:"Short Period",default:7,min:1,max:100,step:1,tooltip:"Fast SMA period (~10% of long period; Chande default: 7)"},{key:"longPeriod",type:"number",label:"Long Period",default:65,min:2,max:500,step:1,tooltip:"Slow SMA period (~13 weeks daily; Chande default: 65)"},{key:"threshold",type:"number",label:"Threshold",default:3,min:0,max:20,step:.5,tooltip:"Trend/range classification level (Chande default: 3%)"}],plots:[{key:"ravi",type:"line",title:"RAVI",style:{color:"#ffeb3b",lineWidth:2}}],levels(t){const o=(t==null?void 0:t.settings)??t??{};return[{price:Math.min(20,Math.max(0,Number(o.threshold)||0)),title:"Threshold",color:"#ff5252",lineStyle:"dashed"},{price:0,title:"Zero Line",color:"#787b86",lineStyle:"dotted"}]},calc(t,o){const i=Math.max(1,Math.floor(Number(o.shortPeriod)||7)),s=Math.max(2,Math.floor(Number(o.longPeriod)||65)),d=t.length,n=new Array(d).fill(NaN);if(i>=s)return{ravi:r(n)};const h=t.map(e=>e.close),c=l(h,i),m=l(h,s);for(let e=0;e<d;e++){if(!Number.isFinite(c[e])||!Number.isFinite(m[e]))continue;const a=m[e];Math.abs(a)<=1e-10||(n[e]=Math.abs(c[e]-a)/Math.abs(a)*100)}return{ravi:r(n)}}})}export{u as default};
